use std::{fs,path::{Path,PathBuf},process::Command,time::{SystemTime,UNIX_EPOCH}};
use rusqlite::{Connection,params};use serde_json::{Value,json};
static SEQ:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
fn root()->PathBuf{std::env::temp_dir().join(format!("atlas-trash-{}-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos(),SEQ.fetch_add(1,std::sync::atomic::Ordering::Relaxed)))}
fn action(p:&Path,args:&[&str])->Value{let o=Command::new(env!("CARGO_BIN_EXE_atlas-native-storage-contract")).arg(args[0]).arg(p).args(&args[1..]).output().unwrap();assert!(o.status.success(),"{}: {}",args[0],String::from_utf8_lossy(&o.stderr));serde_json::from_slice(&o.stdout).unwrap()}
fn setup()->(PathBuf,String,String){let p=root();action(&p,&["create-workspace"]);let a=action(&p,&["create-note","один","содержимое"])["id"].as_str().unwrap().to_string();let b=action(&p,&["create-note","два","другой"])["id"].as_str().unwrap().to_string();let board=json!({"objects":[{"id":a,"x":45,"y":-12},{"id":b,"x":1,"y":2}],"edges":[{"id":"edge","from":a,"to":b}],"stacks":[]});action(&p,&["put-board",&board.to_string()]);(p,a,b)}
#[test]fn restore_note_and_link(){let(p,a,_)=setup();action(&p,&["delete-objects",&json!([a]).to_string()]);let board=action(&p,&["get-board"]);assert!(!board["objects"].as_array().unwrap().iter().any(|o|o["id"]==a));assert!(board["edges"].as_array().unwrap().is_empty());let trash=action(&p,&["list-trash"]);assert!(trash.as_array().unwrap().iter().any(|o|o["id"]==a));action(&p,&["restore-objects",&json!([a]).to_string()]);assert_eq!(action(&p,&["get-note",&a])["text"],"содержимое");let board=action(&p,&["get-board"]);assert_eq!(board["edges"][0]["id"],"edge");let o=board["objects"].as_array().unwrap().iter().find(|o|o["id"]==a).unwrap();assert_eq!(o["x"],45);assert_eq!(o["y"],-12);fs::remove_dir_all(p).unwrap();}
#[test]fn purge_only_expired(){let(p,a,b)=setup();action(&p,&["delete-objects",&json!([a,b]).to_string()]);let conn=Connection::open(p.join("atlas.sqlite3")).unwrap();conn.execute("UPDATE trash SET deleted_at=0 WHERE id=?",params![a]).unwrap();drop(conn);action(&p,&["purge-trash"]);let conn=Connection::open(p.join("atlas.sqlite3")).unwrap();let old:i64=conn.query_row("SELECT count(*) FROM objects WHERE id=?",[&a],|r|r.get(0)).unwrap();let recent:i64=conn.query_row("SELECT count(*) FROM trash WHERE id=?",[&b],|r|r.get(0)).unwrap();assert_eq!(old,0);assert_eq!(recent,1);drop(conn);fs::remove_dir_all(p).unwrap();}
#[test]fn restore_conflicting_edge_rolls_back(){let(p,a,b)=setup();action(&p,&["delete-objects",&json!([a]).to_string()]);let conn=Connection::open(p.join("atlas.sqlite3")).unwrap();let conflict=json!({"objects":[],"edges":[{"id":"other","from":a,"to":b}],"stacks":[]});conn.execute("UPDATE board SET data=? WHERE id=1",[conflict.to_string()]).unwrap();drop(conn);let o=Command::new(env!("CARGO_BIN_EXE_atlas-native-storage-contract")).arg("restore-objects").arg(&p).arg(json!([a]).to_string()).output().unwrap();assert!(!o.status.success(),"conflicting pair must reject restoration");let conn=Connection::open(p.join("atlas.sqlite3")).unwrap();let in_trash:i64=conn.query_row("SELECT count(*) FROM trash WHERE id=?",[&a],|r|r.get(0)).unwrap();assert_eq!(in_trash,1);drop(conn);fs::remove_dir_all(p).unwrap();}
#[test]fn restore_preexisting_legacy_duplicate_links(){let(p,a,b)=setup();let conn=Connection::open(p.join("atlas.sqlite3")).unwrap();let mut pair=[a.as_str(),b.as_str()];pair.sort();let key=format!("[\"{}\", \"{}\"]",pair[0],pair[1]);conn.execute("INSERT INTO legacy_edge_pairs(pair,ids) VALUES(?,?)",[key,"[\"\\\"edge\\\"\", \"\\\"edge2\\\"\"]".to_string()]).unwrap();let board=json!({"objects":[{"id":a,"x":1,"y":2},{"id":b,"x":1,"y":2}],"edges":[{"id":"edge","from":a,"to":b},{"id":"edge2","from":a,"to":b}],"stacks":[]});conn.execute("UPDATE board SET data=? WHERE id=1",[board.to_string()]).unwrap();drop(conn);action(&p,&["delete-objects",&json!([a]).to_string()]);let result=action(&p,&["restore-objects",&json!([a]).to_string()]);assert_eq!(result["edges"].as_array().unwrap().len(),2);fs::remove_dir_all(p).unwrap();}
